 useEffect(()=>{let disposed=false,working=false;const poll=async()=>{if(working)return;working=true;try{const response=await fetch('/api/jobs');if(!response.ok)return;const {jobs:all}=await response.json() as {jobs:BackgroundJob[]};if(disposed)return;setJobs(previous=>previous.length===all.length&&previous.every((j,i)=>j.id===all[i].id&&j.updatedAt===all[i].updatedAt&&j.status===all[i].status&&j.progress===all[i].progress)?previous:all);const applied=readLocal<string[]>('applied-jobs',[]);for(const job of all.filter(j=>j.status==='completed'&&j.result&&!applied.includes(j.id))){const stored=await listPapers();if(disposed)return;const current=stored.find(p=>p.id===job.paperId)?(paperRef.current.id===job.paperId?paperRef.current:stored.find(p=>p.id===job.paperId)):undefined;if(current){const updated=current.analysisEdited&&current.analysis?{...current,revisions:[...(current.revisions||[]),{id:crypto.randomUUID(),createdAt:Date.now(),label:'后台解析候选：'+job.title,analysis:job.result!}].slice(-12)}:{...current,analysis:job.result,title:job.result!.title||current.title,analysisEdited:false,revisions:current.analysis?[...(current.revisions||[]),{id:crypto.randomUUID(),createdAt:Date.now(),label:'重新解析前的版本',analysis:current.analysis}].slice(-12):current.revisions};if(!await persist(updated))continue;setToast(current.analysisEdited?'后台解析已完成；你的编辑已保留，新结果可在任务中应用':'解析已完成：'+current.title);}applied.push(job.id);writeLocal('applied-jobs',applied.slice(-400));}}catch{/* Retry transient local service errors on next poll. */}finally{working=false;}};void poll();const timer=setInterval(()=>void poll(),2400);return()=>{disposed=true;clearInterval(timer);};},[]);
