 const visibleJobs=preparation.jobs;
 async function jobAction(id:string,action:'cancel'|'retry'|'delete'){
  if(action==='retry'&&needKey())return;
  try{
   const prior=visibleJobs.find(j=>j.id===id);
   if(action==='retry'&&prior?.provider&&prior.provider!==settings.provider){setSettingsOpen(true);throw new Error(`这条任务使用 ${prior.provider==='codex'?'Codex':'DeepSeek'}，请手动切换到相同助手后继续；选择其他助手可创建新的解析任务。`);}
   if(action==='cancel'){await preparation.cancel(id);return;}
   if(id.startsWith('local-')){
    preparation.discard(id);
    if(action==='retry'&&prior){const target=papersRef.current.find(p=>p.id===prior.paperId);if(target)preparation.enqueue(target,settings);}
    return;
   }
   const response=await fetch('/api/jobs/'+id+(action==='delete'?'':'/'+action),{method:action==='delete'?'DELETE':'POST',headers:{'Content-Type':'application/json'},body:action==='delete'?undefined:JSON.stringify(aiRequest(settings))});
   const value=await response.json();if(!response.ok)throw new Error(value.error||'任务操作未完成');
   preparation.discard(id);await refreshJobs();
   if(action==='retry'&&value.status==='preparing'){
    const target=papersRef.current.find(p=>p.id===value.paperId);
    if(!target)throw new Error('这篇文献已不在文献库中，请先恢复包含 PDF 的完整备份');
    preparation.enqueue(target,settings,value);
   }
  }catch(e){setError((e as Error).message);}
 }
