 async function openPaper(p:Paper,record=true){if(p.demo)p=loadDemo();if(busy||chatBusy||figureBusy){setToast('请等待当前任务完成，或先取消解析');return;}const before=record?snapshotLocation():null;const sequence=++openSequence.current;setError('');try{const bytes=p.demo?new Uint8Array(await(await fetch('/demo.pdf')).arrayBuffer()):await getPdf(p.id);if(sequence!==openSequence.current)return;if(before)pushLocation(before);pendingLocation.current=null;setDocumentId('main');documentRef.current='main';p={...p,lastReadAt:Date.now()};paperRef.current=p;setPdf(bytes);setPaper(p);void persist(p);writeLocal('last-paper',p.id);const savedPage=readLocal('remember-location',true)?readLocal('page-'+p.id,1):1;setPage(savedPage);const savedSection=savedReadingSection(p,savedPage);setActive(savedSection?.id||'');if(savedPage>1&&savedSection)setTimeout(()=>document.getElementById('section-'+savedSection.id)?.scrollIntoView({block:'start',behavior:'instant'}),120);setTab('analysis');setChatOpen(false);setTranslation(null);reader.current?.scrollTo({top:0});}catch{setError('无法读取这篇文献，请重新导入 PDF。');}}
 async function importFiles(files:File[]){if(!files.length)return;if(busy||chatBusy||figureBusy){setToast('请等待当前操作完成');return;}setError('');let count=0,duplicates=0;try{for(const file of files){if(!file.name.toLowerCase().endsWith('.pdf'))continue;if(file.size>150*1024*1024)throw new Error(file.name+' 超过 150 MB');setBusy('正在导入 '+file.name);const bytes=new Uint8Array(await file.arrayBuffer());const fileHash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(x=>x.toString(16).padStart(2,'0')).join('');if(papersRef.current.some(p=>p.fileHash===fileHash)){duplicates++;continue;}const result=await extractPdf(bytes.slice());const doi=result.pages.slice(0,2).join(' ').match(/10\.\d{4,9}\/[-._;()/:A-Z0-9]+/i)?.[0]?.replace(/[.,;]+$/,'');const p:Paper={id:crypto.randomUUID(),title:result.title||file.name.replace(/\.pdf$/i,''),fileName:file.name,category:'基础医学',folderId:folder==='all'||folder==='starred'?'reading':folder,addedAt:Date.now(),pageCount:result.pageCount,pages:result.pages,outline:result.outline,notes:'',starred:false,fileHash,doi,readingStatus:'unread'};await savePaper(p,bytes);papersRef.current=[p,...papersRef.current];setPapers(papersRef.current);paperRef.current=p;setPaper(p);writeLocal('last-paper',p.id);setDocumentId('main');documentRef.current='main';setPdf(bytes);setPage(1);setActive('');setTab('analysis');setChatOpen(false);count++;}setToast(`已导入 ${count} 篇文献${duplicates?'，跳过 '+duplicates+' 篇相同 PDF':''}`);}catch(e){setError((e as Error).message||'PDF 无法读取');}finally{setBusy('');if(fileInput.current)fileInput.current.value='';}}
 function snapshotLocation():ReadingLocation|null{if(!pdf||!viewer.current)return null;return {paperId:paperRef.current.id,documentId:documentRef.current,view:viewer.current.getViewState(),active,tab,readerTop:reader.current?.scrollTop||0,readerMode:readLocal('reader-mode','focus')};}
