 function pdfReady(){requestAnimationFrame(()=>requestAnimationFrame(()=>{const loc=pendingLocation.current;if(loc&&loc.paperId===paperRef.current.id&&loc.documentId===documentRef.current){pendingLocation.current=null;restorePane(loc);}const target=pendingTarget.current;if(target&&target.paperId===paperRef.current.id&&target.documentId===documentRef.current){pendingTarget.current=null;void viewer.current?.revealTarget(target.target);}if(pendingCrop.current){viewer.current?.startCrop?.(pendingCrop.current);pendingCrop.current=null;}}));}
 async function navigateHistory(direction:'back'|'forward'){if(busy||figureBusy||chatBusy)return;const stack=history.current[direction],target=stack.at(-1);if(!target)return;const current=snapshotLocation();const selected=target.paperId===paperRef.current.id?paperRef.current:target.paperId===demoPaper.id?loadDemo():papersRef.current.find(p=>p.id===target.paperId);if(!selected){stack.pop();syncHistory();setToast('该文献已从库中移除');return;}try{const same=selected.id===paperRef.current.id&&target.documentId===documentRef.current;if(!same){const sequence=++openSequence.current;const bytes=target.documentId==='main'?(selected.demo?new Uint8Array(await(await fetch('/demo.pdf')).arrayBuffer()):await getPdf(selected.id)):await getSupplementPdf(selected.id,target.documentId);if(sequence!==openSequence.current)return;if(!bytes)throw new Error('无法读取保存的 PDF');pendingLocation.current=target;paperRef.current=selected;setPaper(selected);documentRef.current=target.documentId;setDocumentId(target.documentId);setPdf(bytes);writeLocal('last-paper',selected.id);}setPage(target.view.page);setActive(target.active);setTab(target.tab);stack.pop();if(current)history.current[direction==='back'?'forward':'back'].push(current);syncHistory();if(same)restorePane(target);}catch(e){setError((e as Error).message);}}
 async function goDocument(id:string,p:number,record=true){const source=paperRef.current;if(id!=='main'&&!source.supplements?.some(s=>s.id===id)){setToast('这份补充 PDF 尚未关联');return;}const max=id==='main'?source.pageCount:source.supplements!.find(s=>s.id===id)!.pageCount;const target=Math.max(1,Math.min(max,p));if(id===documentRef.current){if(record)rememberLocation();setPage(target);viewer.current?.goToPage(target);return;}const before=record?snapshotLocation():null,sequence=++openSequence.current;try{const bytes=id==='main'?(source.demo?new Uint8Array(await(await fetch('/demo.pdf')).arrayBuffer()):await getPdf(source.id)):await getSupplementPdf(source.id,id);if(sequence!==openSequence.current||paperRef.current.id!==source.id)return;if(!bytes)throw new Error('PDF 附件无法读取');if(before)pushLocation(before);pendingLocation.current=null;documentRef.current=id;setDocumentId(id);setPage(target);setPdf(bytes);}catch(e){setError((e as Error).message);}}
 function goto(id:string,p:number,figureId?:string){rememberLocation();writeLocal('reading-section-'+paperRef.current.id,{id,page:p});const section=paperRef.current.analysis?.sections.find(s=>s.id===id),figure=section?.figures.find(f=>f.id===figureId);void preciseJump((figure?.page===p?figure.source:!figure&&section?.page===p?section.source:undefined)||{page:p,text:figure?figureText(figure.title):section?.title},'main',false);setActive(id);setTab('analysis');setTimeout(()=>{const section=document.getElementById('section-'+id) as HTMLDetailsElement|null;if(section)section.open=true;const target=figureId?document.getElementById('figure-'+figureId) as HTMLDetailsElement|null:section;if(target){target.open=true;target.scrollIntoView({behavior:'smooth',block:'start'});}},50);}
 async function preciseJump(target:PdfTarget,docId='main',record=true){
  setPinsOpen(false);const sourceId=paperRef.current.id,same=docId===documentRef.current;
  if(!same)pendingTarget.current={paperId:sourceId,documentId:docId,target};
  await goDocument(docId,target.page,record);
  if(same&&paperRef.current.id===sourceId)await viewer.current?.revealTarget(target);
 }
 async function pinFigure(f:Figure,panel?:Panel){
  const source=paperRef.current;setToast('正在准备固定图…');
  try{let image=panel?.image;if(!image){const bytes=source.demo?new Uint8Array(await(await fetch('/demo.pdf')).arrayBuffer()):await getPdf(source.id);if(!bytes)throw new Error('原文 PDF 无法读取');image=await renderPdfPage(bytes,f.page);}
   if(paperRef.current.id!==source.id)return;
   const item:PinnedFigure={id:f.id+':'+(panel?.label||'whole'),title:f.title+(panel?' · '+panel.label:''),image,target:{page:f.page,...(panel?.crop?{region:panel.crop}:{text:figureText(f.title)})},fullPage:!panel?.image};
   setPins(previous=>[...previous.filter(p=>p.id!==item.id).slice(-1),item]);setPinsOpen(true);setToast('已固定在左侧；最多对照两张，继续固定会替换较早的一张');
  }catch(e){setError((e as Error).message);}
 }
 async function openSearchHit(hit:SearchHit){
  const source=searchablePapers.find(p=>p.id===hit.paperId);if(!source)return;
  if(busy||chatBusy||figureBusy){setToast('请等待当前操作完成');return;}
  const same=source.id===paperRef.current.id&&hit.documentId===documentRef.current;
  if(source.id!==paperRef.current.id)await openPaper(source);else rememberLocation();
  if(paperRef.current.id!==source.id)return;
  setSearchOpen(false);setPinsOpen(false);
  if(hit.kind==='笔记'){setTab('notes');setNoteEdit(false);}else{setTab('analysis');if(hit.sectionId)setActive(hit.sectionId);}
  setSearchDestination(hit);
  if(hit.target){const target={...hit.target,text:hit.kind==='子图'||hit.field==='caption'?figureText(hit.target.text||''):hit.target.text};
    if(!same)pendingTarget.current={paperId:source.id,documentId:hit.documentId,target};
    await goDocument(hit.documentId,target.page,false);if(same)void viewer.current?.revealTarget(target);
  }
 }
 function annotationKey(key:string){const id=paperRef.current.id,map=readLocal<Record<string,string>>('annotation-map-'+id,{});if(map[documentRef.current]!==key)writeLocal('annotation-map-'+id,{...map,[documentRef.current]:key});}
 function openReference(reference:string){const found=resolveReference(paperRef.current,reference);if(found){if(found.sectionId)goto(found.sectionId,found.page,found.figureId);else void goDocument(found.documentId,found.page);setSupplementOpen(false);}else{setSupplementReference(reference);setSupplementOpen(true);}}
 async function attachSupplement(file:File){const source=paperRef.current;if(source.demo)throw new Error('请先导入真实文献');if(file.size>150*1024*1024)throw new Error('补充 PDF 最大 150 MB');const bytes=new Uint8Array(await file.arrayBuffer()),hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(x=>x.toString(16).padStart(2,'0')).join('');if(source.supplements?.some(x=>x.fileHash===hash))throw new Error('这份补充 PDF 已关联');const result=await extractPdf(bytes.slice()),latest=paperRef.current.id===source.id?paperRef.current:papersRef.current.find(x=>x.id===source.id);if(!latest)throw new Error('原文献已移除');const supplement={id:crypto.randomUUID(),title:file.name.replace(/\.pdf$/i,''),fileName:file.name,pageCount:result.pageCount,pages:result.pages,addedAt:Date.now(),fileHash:hash};const updated={...latest,supplements:[...(latest.supplements||[]),supplement]};await saveSupplement(updated,supplement.id,bytes);await persist(updated);}
 async function updateSupplementLinks(links:SupplementLink[]){return persist({...paperRef.current,supplementLinks:links});}
 async function appendAnnotations(items:PdfHighlight[]){const source=paperRef.current,doc=documentRef.current;const result=appendHighlightNotes(source.notes,items,doc,documentTitle(source,doc),source.highlightNoteIds);if(!result.added){setToast('所选摘录已在笔记中');return true;}const saved=await persist({...source,notes:result.notes,highlightNoteIds:result.ids});if(saved)setToast('已追加 '+result.added+' 条摘录到研究笔记');return saved;}
 function beginWebsiteEdit(){const p=paperRef.current;setWebsiteDraft({doi:p.doi||'',url:p.officialUrl||''});setWebsiteEdit(true);}
 async function saveWebsite(){if(websiteDraft.url.trim()&&!safeOfficialUrl(websiteDraft.url)){setToast('请填写完整的 HTTPS 官网地址');return;}if(websiteDraft.doi.trim()&&!normalizeDoi(websiteDraft.doi)){setToast('请填写有效 DOI，例如 10.1038/…');return;}if(await persist({...paperRef.current,doi:normalizeDoi(websiteDraft.doi),officialUrl:safeOfficialUrl(websiteDraft.url)})){setWebsiteEdit(false);setToast('官网链接已保存');}}
 async function saveRename(){if(!rename?.name.trim())return;if(rename.kind==='folder'){setFolders(prev=>prev.map(x=>x.id===rename.id?{...x,name:rename.name.trim()}:x));setRename(null);return;}const latest=paperRef.current.id===rename.id?paperRef.current:papersRef.current.find(x=>x.id===rename.id);if(latest&&await persist({...latest,title:rename.name.trim()})){setRename(null);setToast('文献已重命名');}}

 function bindSource(section:Section,figure?:Figure){
  sourceBinding.current={paperId:paperRef.current.id,sectionId:section.id,figureId:figure?.id};setPinsOpen(false);setCropTarget(null);
  const page=figure?.page||section.page;
  if(documentRef.current!=='main'){pendingCrop.current=page;void goDocument('main',page);}else{rememberLocation();viewer.current?.startCrop?.(page);}
  setToast('在 PDF 上框选对应段落或图片，保存后可一键直达；Esc 取消');
 }
 function startCrop(sectionId:string,figure:Figure,panel?:Panel){sourceBinding.current=null;setPinsOpen(false);if(panel?.image&&panel.crop){setFocus({paper:paperRef.current,sectionId,figure,panel,crop:{page:figure.page,dataUrl:panel.image,region:panel.crop}});return;}setCropTarget({paperId:paper.id,sectionId,figure,panel});if(documentRef.current!=='main'){pendingCrop.current=figure.page;void goDocument('main',figure.page);}else{rememberLocation();viewer.current?.startCrop?.(figure.page);}setToast('在 PDF 上拖出要精读的子图范围');}
 function receiveCrop(crop:PdfCrop){const current=paperRef.current;
  const binding=sourceBinding.current;sourceBinding.current=null;
  if(binding?.paperId===current.id&&current.analysis){const source={page:crop.page,region:crop.region};const analysis={...current.analysis,sections:current.analysis.sections.map(s=>s.id!==binding.sectionId?s:binding.figureId?{...s,figures:s.figures.map(f=>f.id===binding.figureId?{...f,source}:f)}:{...s,source})};void persist(revisePaper(current,analysis,'校准原文位置'));setToast('原文位置已保存，下次点击可直达框选区域');return;}
if(!current.analysis?.sections.length){setToast('请先生成文章解析，再将裁图关联到小节');return;}const target=cropTarget?.paperId===current.id?cropTarget:null;const section=current.analysis.sections.find(s=>s.id===(target?.sectionId||active))||current.analysis.sections[0];const figure=target?.figure||section.figures.find(f=>f.page===crop.page)||{id:crypto.randomUUID(),title:'子图精读',page:crop.page,caption:'',panels:[]};setFocus({paper:current,sectionId:section.id,figure,panel:target?.panel,crop});setCropTarget(null);}
 function saveFocus(panel:Panel){if(!focus)return;const current=paperRef.current.id===focus.paper.id?paperRef.current:papersRef.current.find(p=>p.id===focus.paper.id);if(!current?.analysis)return;const analysis={...current.analysis,sections:current.analysis.sections.map(s=>{if(s.id!==focus.sectionId)return s;const exists=s.figures.some(f=>f.id===focus.figure.id);const figures=exists?s.figures:[...s.figures,focus.figure];return {...s,figures:figures.map(f=>{if(f.id!==focus.figure.id)return f;const index=focus.panel?f.panels.findIndex(p=>p.label===focus.panel!.label):-1;return {...f,panels:index<0?[...f.panels,panel]:f.panels.map((p,i)=>i===index?panel:p)};})};})};void persist(revisePaper(current,analysis,'子图精读 '+panel.label));setToast('子图与详细解析已保存');}
 const [codexStatus,setCodexStatus]=useState({available:false,authenticated:false,message:'正在检查本机 Codex 登录'});
 async function refreshCodex(){try{const r=await fetch('/api/codex/status');if(!r.ok)throw new Error();setCodexStatus(await r.json());}catch{setCodexStatus({available:false,authenticated:false,message:'无法检查本机 Codex，请确认本地服务已更新'});}}
 useEffect(()=>{if(settings.provider==='codex')void refreshCodex();},[settings.provider,settingsOpen]);
 const hasKey=settings.provider==='codex'?codexStatus.authenticated:!!settings.apiKey.trim()||serverKey;
 function needKey(){if(hasKey)return false;setSettingsOpen(true);setToast(settings.provider==='codex'?codexStatus.message:'填入 DeepSeek API Key 后即可使用 AI 功能');return true;}
 async function analyze(ids?:string[]){
  if(needKey()||busy)return;
  const targets=ids?papersRef.current.filter(p=>ids.includes(p.id)):[paperRef.current];
  if(targets.every(p=>p.demo)){setToast('演示已包含解析；导入你的 PDF 即可生成真实解析');return;}
  setError('');setJobsOpen(true);setManagerOpen(false);
  for(const current of targets.filter(p=>!p.demo)){
   const existing=visibleJobs.find(j=>j.paperId===current.id&&['preparing','queued','running'].includes(j.status));
   if(existing){if(existing.status==='preparing'&&!preparation.preparingIds.includes(existing.id))void jobAction(existing.id,'retry');continue;}
   preparation.enqueue(current,settings);
  }
  setToast('已加入后台任务，页面准备期间也可继续阅读');
 }
 async function ask(text=question){if(!text.trim()||chatBusy)return;if(needKey())return;const current=paperRef.current;const messages=[...chat,{role:'user' as const,content:text.trim()}];setQuestion('');setChat(messages);setChatOpen(true);setChatBusy(true);setError('');try{const {answer}=await api<{answer:string}>('ask',{pages:current.pages,analysis:current.analysis,question:text,messages:chat.slice(-12),...aiRequest(settings)});const next=[...messages,{role:'assistant' as const,content:answer,provider:settings.provider}];setChat(next);writeLocal('chat-'+current.id,next);}catch(e){setChat([...messages,{role:'assistant',content:'请求未完成：'+(e as Error).message}]);}finally{setChatBusy(false);}}
 async function translate(){if(!selection)return;if(needKey())return;setTranslateBusy(true);const text=selection.text;const sourceId=paper.id,sourcePage=page;setSelection(null);setTranslation({text,translation:'',terms:[],explanation:'',paperId:sourceId,page:sourcePage});try{const result=await api<{translation:string;terms:string[];explanation:string}>('translate',{text,...aiRequest(settings)});if(paperRef.current.id===sourceId)setTranslation({text,...result,paperId:sourceId,page:sourcePage});}catch(e){if(paperRef.current.id===sourceId)setTranslation({text,translation:'翻译未完成：'+(e as Error).message,terms:[],explanation:'',paperId:sourceId,page:sourcePage});}finally{setTranslateBusy(false);}}
 async function deepFigure(sectionId:string,figure:Figure){if(needKey())return;if(!viewer.current)return;setFigureBusy(figure.id);setError('');try{const sourceId=paper.id;const bytes=paper.demo?new Uint8Array(await(await fetch('/demo.pdf')).arrayBuffer()):await getPdf(sourceId);if(!bytes)throw new Error('原始 PDF 无法读取');const image=await renderPdfPage(bytes,figure.page);const updated=await api<Figure>('figure',{pages:paper.pages,figure,pageImage:image,...aiRequest(settings)});const latest=paperRef.current;if(latest.id!==sourceId)return;persist(revisePaper(latest,{...latest.analysis!,sections:latest.analysis!.sections.map(s=>s.id===sectionId?{...s,figures:s.figures.map(f=>f.id===figure.id?{...updated,id:f.id,page:f.page}:f)}:s)},'逐图细读 '+figure.title));setToast('已根据原图更新子图拆解');}catch(e){setError((e as Error).message);}finally{setFigureBusy('');}}
 async function previewFigure(f:Figure){try{const bytes=paper.demo?new Uint8Array(await(await fetch('/demo.pdf')).arrayBuffer()):await getPdf(paper.id);if(!bytes)throw new Error('原始 PDF 无法读取');const image=await renderPdfPage(bytes,f.page);if(image)setImagePreview({title:f.title,url:image});}catch(e){setError((e as Error).message);}}
 function resize(which:'library'|'pdf'|'nav',e:React.PointerEvent){e.preventDefault();const start=e.clientX,initial=widths[which];const container=document.querySelector('.reading-columns')?.getBoundingClientRect().width||1000;document.body.classList.add('resizing');const move=(event:PointerEvent)=>setWidths(w=>({...w,[which]:which==='pdf'?Math.min(66,Math.max(26,initial+(event.clientX-start)/container*100)):which==='library'?Math.min(340,Math.max(172,initial+event.clientX-start)):Math.min(360,Math.max(190,initial+start-event.clientX))}));const up=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);document.body.classList.remove('resizing');};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up);}
 function reorder(id:string,delta:number){const ids=orderedSections.map(s=>s.id);const index=ids.indexOf(id),next=index+delta;if(next<0||next>=ids.length)return;[ids[index],ids[next]]=[ids[next],ids[index]];setNavOrder(ids);writeLocal('nav-'+paper.id,ids);}
 const orderedSections=[...(paper.analysis?.sections||[])].sort((a,b)=>{const ai=navOrder.indexOf(a.id),bi=navOrder.indexOf(b.id);return(ai<0?999:ai)-(bi<0?999:bi);});
 const visiblePapers=sortedPapers(papers,sidebarSort).filter(p=>(folder==='all'||(folder==='starred'?p.starred:p.folderId===folder))&&p.title.toLowerCase().includes(query.toLowerCase()));
 const figures=paper.analysis?.sections.flatMap(s=>s.figures)||[];
 const noteHeadings=paper.notes.split('\n').filter(l=>/^#{1,4}\s/.test(l));
 return <ReadingLinksContext.Provider value={{onReference:openReference,onPage:(id,p)=>void goDocument(id,p)}}><div className="app" onDragOver={e=>{if(e.dataTransfer.types.includes('Files')){e.preventDefault();setDragOver(true);}}} onDrop={e=>{e.preventDefault();setDragOver(false);void importFiles(Array.from(e.dataTransfer.files));}}>
  <input ref={fileInput} type="file" accept="application/pdf,.pdf" multiple hidden onChange={e=>void importFiles(Array.from(e.target.files||[]))}/>
  <TooltipLayer/><header className="titlebar"><div className="brand"><span className="brand-icon"><BookOpen size={19}/></span><span>PaperRead</span></div><div className="top-divider"/><button className="icon-btn" title={library?'隐藏文献库':'显示文献库'} onClick={()=>setLibrary(!library)}>{library?<PanelLeftClose size={18}/>:<PanelLeftOpen size={18}/>}</button><div className="breadcrumb"><span>我的文献库</span><ChevronRight size={13}/><b>{paper.demo?'交互演示':paper.category}</b></div><div className="title-actions"><span className="local-badge"><span/> 本地文献库</span><button className="icon-btn" title="文献库管理" onClick={()=>setManagerOpen(true)}><LibraryBig size={18}/></button><button className="icon-btn" title="完整备份与恢复" onClick={()=>setBackupOpen(true)}><Archive size={18}/></button><button className="icon-btn" title="后台解析任务" onClick={()=>setJobsOpen(true)}><ListTodo size={18}/>{visibleJobs.filter(j=>['preparing','running','queued'].includes(j.status)).length>0&&<span className="task-badge">{visibleJobs.filter(j=>['preparing','running','queued'].includes(j.status)).length}</span>}</button><button className="icon-btn" title="切换明暗主题" onClick={()=>setTheme(theme==='light'?'dark':'light')}>{theme==='light'?<Moon size={17}/>:<Sun size={17}/>}</button><button className="primary-button small" onClick={()=>fileInput.current?.click()}><Plus size={16}/>导入文献</button></div></header>
  <main className="workspace">
   {library&&<><aside className="library" style={{width:widths.library}}><div className="library-title"><span>文献空间</span><button className="icon-btn tiny" title="新建文件夹" onClick={()=>setNewFolder(true)}><Plus size={16}/></button></div><label className="library-search"><Search size={14}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索文献"/><kbd>⌕</kbd></label><button className={'library-nav '+(folder==='all'?'selected':'')} onClick={()=>setFolder('all')}><BookOpen size={16}/>全部文献<span>{papers.length}</span></button><button className={'library-nav '+(folder==='starred'?'selected':'')} onClick={()=>setFolder('starred')}><Star size={16}/>我的收藏<span>{papers.filter(p=>p.starred).length}</span></button><div className="library-label">文件夹<button className="icon-btn tiny" title="添加文件夹" onClick={()=>setNewFolder(true)}><Plus size={13}/></button></div>{folders.map(f=><div className="folder-row" key={f.id}><button className={'library-nav folder '+(folder===f.id?'selected':'')} onClick={()=>setFolder(f.id)} onDragOver={e=>e.preventDefault()} onDrop={e=>{const id=e.dataTransfer.getData('paper-id');if(id){e.stopPropagation();const target=papers.find(p=>p.id===id);if(target){const next={...target,folderId:f.id};savePaper(next);setPapers(ps=>ps.map(p=>p.id===id?next:p));if(paper.id===id)setPaper(next);setToast('已移入 '+f.name);}}}}><Folder size={16}/>{f.name}<span>{papers.filter(p=>p.folderId===f.id).length||''}</span></button><button className="icon-btn tiny" title={"重命名分区 "+f.name} onClick={()=>setRename({kind:'folder',id:f.id,name:f.name})}><PencilLine size={12}/></button></div>)}
    <label className="library-sort">排序<select aria-label="文献空间排序" value={sidebarSort} onChange={e=>{setSidebarSort(e.target.value);writeLocal('sidebar-sort',e.target.value);}}><option value="read">最近阅读时间</option><option value="name">文献名称</option><option value="added">最近导入时间</option></select></label><div className="library-label recent-label">{folder==='all'?'最近阅读':folder==='starred'?'已收藏':folders.find(f=>f.id===folder)?.name}<span>{visiblePapers.length}</span></div><div className="paper-list">{visiblePapers.map(p=><div className="library-paper-row" key={p.id}><button draggable onDragStart={e=>e.dataTransfer.setData('paper-id',p.id)} key={p.id} className={'paper-item '+(p.id===paper.id?'active':'')} onClick={()=>void openPaper(p)}><span className="paper-file-icon"><FileText size={18}/></span><div><strong>{p.title}</strong><span>{p.category} · {p.pageCount} 页{p.lastReadAt&&<small className="last-read-date">{new Date(p.lastReadAt).toLocaleDateString('zh-CN',{month:'numeric',day:'numeric'})} 阅读</small>}</span></div>{p.starred&&<Star size={11} className="star-mini"/>}</button><button className="icon-btn tiny" title={"重命名文献 "+p.title} onClick={()=>setRename({kind:'paper',id:p.id,name:p.title})}><PencilLine size={12}/></button></div>)}{!visiblePapers.length&&<div className="library-empty"><FileText size={23}/><p>{query?'没有匹配的文献':'把下一篇灵感放进来'}</p><button onClick={()=>fileInput.current?.click()}>导入 PDF <ArrowUpRight size={12}/></button></div>}<button className={'paper-item demo-item '+(paper.demo?'active':'')} onClick={()=>void openPaper(demoPaper)}><span className="paper-file-icon demo"><FlaskConical size={18}/></span><div><strong>从一篇文献开始</strong><span>教学演示 · 探索工作台</span></div></button></div><button className="library-trash-link" onClick={()=>setTrashOpen(true)}><Trash2 size={14}/>回收站</button><div className="library-bottom"><span className="avatar">研</span><div><strong>我的研究空间</strong><span>保持好奇，读懂每个发现</span></div><button className="icon-btn" title="设置" data-help="外观、阅读习惯、Codex / DeepSeek、备份与后台任务" onClick={()=>setSettingsOpen(true)}><Settings2 size={18}/></button></div></aside><div className="resize-handle" onPointerDown={e=>resize('library',e)} role="separator" aria-label="调整文献库宽度"/></>}
   <section className="main-area"><div className="document-bar"><div className="document-heading"><span className="document-type"><FileText size={17}/></span><div><strong title={paper.title}>{paper.title}</strong><span>{paper.demo?'交互演示 · 非真实研究数据':paper.fileName}<i/> {paper.pageCount} 页 {paper.analysis&&<><i/><span className="parsed"><CheckCircle2 size={11}/> 已解析</span></>}</span></div></div><div className="document-actions"><button className="icon-btn" title="统一搜索 · ⌘ K" onClick={()=>setSearchOpen(true)}><Search size={16}/></button>{!paper.demo&&(officialUrl(paper)?<a className="official-link" title="打开文献期刊官网" href={officialUrl(paper)} target="_blank" rel="noreferrer">期刊官网<ArrowUpRight size={12}/></a>:<button className="official-link" title="添加 DOI 或官网链接" onClick={beginWebsiteEdit}>添加官网链接<Link2 size={12}/></button>)}{!paper.demo&&<button className="icon-btn tiny" title="编辑官网链接" onClick={beginWebsiteEdit}><PencilLine size={12}/></button>}{paper.demo?<span className="demo-badge">教学示例</span>:<><button className={'icon-btn '+(paper.starred?'favorite':'')} title="收藏文献" onClick={()=>persist({...paper,starred:!paper.starred})}><Star size={16} fill={paper.starred?'currentColor':'none'}/></button><select title="移动到文件夹" value={paper.folderId} onChange={e=>persist({...paper,folderId:e.target.value})}>{folders.map(f=><option key={f.id} value={f.id}>{f.name}</option>)}</select></>}<button className="icon-btn" title="导出 Markdown" onClick={()=>downloadText(paper.title+'.md',exportMarkdown(paper))}><Download size={16}/></button>{!paper.demo&&<button className="icon-btn" title="移入回收站" disabled={!!busy||chatBusy||!!figureBusy} onClick={()=>void removePapers([paper.id])}><Trash2 size={15}/></button>}<button className="icon-btn" title={right?'隐藏导航':'显示导航'} onClick={()=>setRight(!right)}>{right?<PanelRightClose size={17}/>:<PanelRightOpen size={17}/>}</button></div></div>
   {error&&<div className="error-banner" role="alert">{error}<button className="icon-btn tiny" onClick={()=>setError('')}><X size={14}/></button></div>}
   <div className="body-columns"><div className="reading-columns">
    <div className={"pdf-column "+(pinsOpen&&pins.length?'has-pinned-figures':'')} style={{width:widths.pdf+'%'}}><div className="pdf-document-picker"><select aria-label="选择正文或补充 PDF" value={documentId} onChange={e=>void goDocument(e.target.value,readLocal('page-'+paper.id+(e.target.value==='main'?'':'-'+e.target.value),1))}><option value="main">正文 PDF</option>{(paper.supplements||[]).map(s=><option key={s.id} value={s.id}>{s.title}</option>)}</select><button className="subtle-button" onClick={()=>{setSupplementReference('');setSupplementOpen(true);}}>补充材料</button></div>{pins.length>0&&!pinsOpen&&<button className="subtle-button pinned-reopen" onClick={()=>setPinsOpen(true)}>固定看图 · {pins.length}</button>}{pinsOpen&&pins.length>0&&<PinnedFigures items={pins} onClose={()=>setPinsOpen(false)} onRemove={id=>setPins(pins.filter(p=>p.id!==id))} onSource={item=>void preciseJump(item.target)}/>}<PdfViewer onCropCancel={()=>{sourceBinding.current=null;setCropTarget(null);}} onAnnotationKey={annotationKey} ref={viewer} data={pdf} page={page} onPageChange={n=>{setPage(n);writeLocal('page-'+paper.id+(documentId==='main'?'':'-'+documentId),n);}} onReady={pdfReady} onBeforeNavigate={rememberLocation} onAppendHighlights={appendAnnotations} fileName={documentId==='main'?paper.fileName:paper.supplements?.find(s=>s.id===documentId)?.fileName} onCrop={documentId==='main'?receiveCrop:undefined}/></div>
    <div className="resize-handle main-resize" role="separator" aria-label="调整 PDF 与解析区宽度" onPointerDown={e=>resize('pdf',e)}><span/></div>
    <section className="analysis-column"><div className="panel-heading"><div className="segmented"><button className={tab==='analysis'?'active':''} onClick={()=>setTab('analysis')}><Sparkles size={14}/>深度解析</button><button className={tab==='notes'?'active':''} onClick={()=>setTab('notes')}><PencilLine size={14}/>我的笔记</button></div><div className="heading-actions"><button className="icon-btn tiny" title="返回上一阅读位置" disabled={!navCounts.back||!!busy||!!figureBusy||chatBusy} onClick={()=>void navigateHistory('back')}><ChevronRight size={15} style={{transform:'rotate(180deg)'}}/></button><button className="icon-btn tiny" title="前进阅读位置" disabled={!navCounts.forward||!!busy||!!figureBusy||chatBusy} onClick={()=>void navigateHistory('forward')}><ChevronRight size={15}/></button><span className="sync-badge" title="点击目录与逻辑节点，同步定位 PDF"><Link2 size={12}/>联动</span><button className="icon-btn tiny" title="重新解析" disabled={!!busy} onClick={()=>void analyze()}><RotateCcw size={14}/></button></div></div>
     <AnalysisReader pendingJob={visibleJobs.find(j=>j.paperId===paper.id&&['preparing','queued','running'].includes(j.status))} onJobs={()=>setJobsOpen(true)} paper={paper} active={active} tab={tab} readerRef={reader} noteEdit={noteEdit} onNoteEdit={setNoteEdit} onPersist={p=>void persist(p)} onGo={goto} onAnalyze={()=>void analyze()} onBind={bindSource} onPin={(f,p)=>void pinFigure(f,p)} onPreview={f=>void previewFigure(f)} onDeepFigure={(id,f)=>void deepFigure(id,f)} onCrop={startCrop} figureBusy={figureBusy} busy={busy} hasKey={hasKey}/>
     <div className="chat-dock">{chatOpen&&<div className="chat-history"><div className="chat-history-header"><span><MessageSquare size={13}/>与这篇文献对话</span><button className="icon-btn tiny" title="收起对话" onClick={()=>setChatOpen(false)}><ChevronDown size={15}/></button></div>{chat.map((m,i)=><div key={i} className={'chat-message '+m.role}><span className="chat-role">{m.role==='user'?'你':m.provider==='codex'?'Codex':m.provider==='deepseek'?'DeepSeek':'阅读助手'}</span><div className="prose"><Markdown>{m.content}</Markdown></div></div>)}{chatBusy&&<div className="thinking"><LoaderCircle size={13} className="spin"/>正在结合原文思考…</div>}</div>}<div className="chat-hints"><button onClick={()=>void ask('请用三句话概括这篇文章的核心创新。')}>核心创新是什么？</button><button onClick={()=>void ask('请按实验顺序，讲解这篇文章的研究设计和每张图解决的问题。')}>逐图讲解研究设计</button>{chat.length>0&&!chatOpen&&<button className="chat-count" onClick={()=>setChatOpen(true)}><MessageSquare size={12}/>{chat.length}</button>}</div><form className="question-box" onSubmit={e=>{e.preventDefault();void ask();}}><Sparkles size={17}/><input aria-label="向文献提问" value={question} onChange={e=>setQuestion(e.target.value)} placeholder="向这篇文献提问，或选中文字翻译…"/><button type="submit" title="发送问题" disabled={chatBusy||!question.trim()}>{chatBusy?<LoaderCircle size={15} className="spin"/>:<ArrowUp size={17}/>}</button></form><div className="chat-foot"><button onClick={()=>setSettingsOpen(true)}><span className={hasKey?'connected-dot':'unconnected-dot'}/>{aiLabel(settings)} <ChevronDown size={10}/></button><span>结合当前文献回答</span><kbd>↵</kbd></div></div>
    </section></div>
    {right&&<><div className="resize-handle" role="separator" aria-label="调整导航宽度" onPointerDown={e=>resize('nav',e)}/><aside className="navigation" style={{width:widths.nav}}><div className="nav-heading"><strong>阅读导航</strong><button className={'icon-btn tiny '+(editNav?'selected':'')} title="自定义导航顺序与可见性" onClick={()=>setEditNav(!editNav)}><Settings2 size={15}/></button></div><div className="nav-tabs"><button className={navTab==='md'?'active':''} onClick={()=>setNavTab('md')}><LayoutList size={13}/>解析目录</button><button className={navTab==='paper'?'active':''} onClick={()=>setNavTab('paper')}><List size={13}/>原文大纲</button></div><div className="nav-scroll">{editNav&&<div className="nav-customize">上下调整顺序，勾选显示章节。<button onClick={()=>{setNavOrder([]);setHiddenNav([]);writeLocal('nav-'+paper.id,[]);writeLocal('hidden-'+paper.id,[]);}}>恢复默认</button></div>}<div className="nav-group-label">{navTab==='md'?'研究脉络':'PDF OUTLINE'}</div>{navTab==='md'?<>{orderedSections.filter(s=>editNav||!hiddenNav.includes(s.id)).map((s,i)=><div className="nav-entry" key={s.id}>{editNav&&<div className="nav-edit-tools"><input aria-label={'显示 '+s.title} type="checkbox" checked={!hiddenNav.includes(s.id)} onChange={()=>{const next=hiddenNav.includes(s.id)?hiddenNav.filter(id=>id!==s.id):[...hiddenNav,s.id];setHiddenNav(next);writeLocal('hidden-'+paper.id,next);}}/><button title="上移" onClick={()=>reorder(s.id,-1)}><ArrowUp size={11}/></button><button title="下移" onClick={()=>reorder(s.id,1)}><ArrowDown size={11}/></button></div>}<button className={'nav-section '+(active===s.id&&tab==='analysis'?'active':'')} onClick={()=>goto(s.id,s.page)}><span className="nav-marker">{String(i+1).padStart(2,'0')}</span><span>{s.title}</span><small>{s.page}</small></button>{s.figures.map(f=><button key={f.id} className="nav-figure" onClick={()=>goto(s.id,f.page,f.id)}><span/><span>{f.title}</span></button>)}</div>)}{!paper.analysis&&<p className="nav-empty">解析后，这里会生成研究逻辑与 Figure 导航。</p>}<div className="nav-group-label notes-nav-title">我的笔记<button className="icon-btn tiny" title="打开笔记" onClick={()=>setTab('notes')}><Plus size={12}/></button></div>{noteHeadings.length?noteHeadings.map((h,i)=><button className="nav-note" key={i} onClick={()=>{setTab('notes');setNoteEdit(false);setTimeout(()=>{const headings=reader.current?.querySelectorAll('.note-preview h1,.note-preview h2,.note-preview h3,.note-preview h4');headings?.[i]?.scrollIntoView({behavior:'smooth'});},40);}}><PencilLine size={12}/>{h.replace(/^#+\s/,'')}</button>):<button className="add-note" onClick={()=>setTab('notes')}><Plus size={13}/>写下第一个想法</button>}</>:<>{(paper.outline.length?paper.outline:paper.pages.map((_,i)=>({title:'第 '+(i+1)+' 页',page:i+1}))).map((o,i)=><button key={i} className={'nav-section '+(page===o.page?'active':'')} onClick={()=>{const related=paper.analysis?.sections.filter(s=>s.page<=o.page).at(-1);if(related)goto(related.id,o.page);else{void goDocument('main',o.page);}}}><span className="nav-marker"><FileText size={12}/></span><span>{o.title}</span><small>{o.page}</small></button>)}</>}</div><div className="reading-progress"><div><span>{documentId==='main'?'原文阅读进度':'补充 PDF 阅读进度'}</span><b>{Math.round(page/Math.max(1,documentId==='main'?paper.pageCount:paper.supplements?.find(s=>s.id===documentId)?.pageCount||1)*100)}%</b></div><div className="progress-track"><span style={{width:page/Math.max(1,documentId==='main'?paper.pageCount:paper.supplements?.find(s=>s.id===documentId)?.pageCount||1)*100+'%'}}/></div><span>第 {page} 页 / 共 {documentId==='main'?paper.pageCount:paper.supplements?.find(s=>s.id===documentId)?.pageCount||1} 页</span></div><div className="nav-tip"><Link2 size={15}/><p>让思路与证据相连<span>点击目录，同时定位解析与原文。</span></p></div></aside></>}
   </div></section>
  </main>
  {searchOpen&&<UnifiedSearch papers={searchablePapers} currentId={paper.id} onGo={h=>void openSearchHit(h)} onClose={()=>setSearchOpen(false)}/>}
  {trashOpen&&<TrashManager onClose={()=>setTrashOpen(false)} onChanged={()=>void refreshLibrary()}/>}
  {managerOpen&&<LibraryManager papers={papers} folders={folders} onUpdate={p=>void persist(p)} onOpen={p=>void openPaper(p)} onDelete={ids=>void removePapers(ids)} onAnalyze={ids=>void analyze(ids)} onImport={()=>fileInput.current?.click()} onClose={()=>setManagerOpen(false)}/>}
  {backupOpen&&<BackupManager onClose={()=>setBackupOpen(false)} onRestored={()=>void refreshLibrary()} onNotify={setToast}/>}
  {jobsOpen&&<JobsDrawer jobs={visibleJobs} preparingIds={preparation.preparingIds} onClose={()=>setJobsOpen(false)} onCancel={id=>void jobAction(id,'cancel')} onRetry={id=>void jobAction(id,'retry')} onDelete={id=>void jobAction(id,'delete')} onOpen={id=>{const p=papersRef.current.find(p=>p.id===id);if(p){void openPaper(p);setJobsOpen(false);}else setToast('这篇文献已不在文献库中');}} onApply={j=>void applyJob(j)}/>}
  {focus&&<FigureFocus paper={focus.paper} figure={focus.figure} panel={focus.panel} crop={focus.crop} settings={settings} hasKey={hasKey} onSettings={()=>setSettingsOpen(true)} onSave={saveFocus} onClose={()=>setFocus(null)}/>}
  {dragOver&&<div className="drop-overlay" onDragLeave={()=>setDragOver(false)}><div><Upload size={40}/><h2>把文献放在这里</h2><p>松开即可导入 PDF，开始你的下一次发现</p></div></div>}
  {selection&&<div className="selection-toolbar" style={{left:selection.x,top:selection.y}}><button onClick={()=>void translate()}><Languages size={15}/>翻译与术语</button><button onClick={()=>{setQuestion('请解释这段原文：\n'+selection.text);setSelection(null);}}><MessageSquare size={14}/>提问</button><button onClick={()=>{persist({...paper,notes:paper.notes+'\n\n> '+selection.text.replace(/\n/g,'\n> ')+'\n\n来源：第 '+page+' 页\n'});setSelection(null);setToast('已摘录到笔记');}}><Quote size={14}/>摘录</button></div>}
  {settingsOpen&&<AppSettings settings={settings} onSettings={setSettings} hasKey={hasKey} codexStatus={codexStatus} onCheckCodex={refreshCodex} theme={theme} onTheme={setTheme} onLibrary={()=>setManagerOpen(true)} onBackup={()=>setBackupOpen(true)} onJobs={()=>setJobsOpen(true)} onClose={()=>setSettingsOpen(false)} onReadingChange={()=>setToast('阅读设置已应用')}/>}
  {!library&&<button className="icon-btn settings-footer-button" title="设置" onClick={()=>setSettingsOpen(true)}><Settings2 size={18}/></button>}
  {supplementOpen&&<SupplementManager paper={paper} reference={supplementReference} onAttach={attachSupplement} onUpdate={updateSupplementLinks} onGo={(id,p)=>{void goDocument(id,p);setSupplementOpen(false);}} onClose={()=>setSupplementOpen(false)}/>}
  {websiteEdit&&<div className="modal-backdrop"><form className="modal reader-modal" onSubmit={e=>{e.preventDefault();void saveWebsite();}}><button className="modal-close icon-btn" type="button" title="关闭官网编辑" onClick={()=>setWebsiteEdit(false)}><X size={18}/></button><h2>文献官网链接</h2><p className="muted">填写 DOI 后自动跳转至出版方；也可以指定期刊文章的 HTTPS 地址。</p><label>DOI<input aria-label="官网 DOI" value={websiteDraft.doi} onChange={e=>setWebsiteDraft({...websiteDraft,doi:e.target.value})} placeholder="10.1038/…"/></label><label>官网地址<input aria-label="官网地址" value={websiteDraft.url} onChange={e=>setWebsiteDraft({...websiteDraft,url:e.target.value})} placeholder="https://…"/></label><div className="modal-actions"><button className="primary-button" type="submit">保存链接</button></div></form></div>}
  {rename&&<div className="modal-backdrop"><form className="modal rename-modal" onSubmit={e=>{e.preventDefault();void saveRename();}}><button className="modal-close icon-btn" title="关闭重命名" type="button" onClick={()=>setRename(null)}><X size={18}/></button><h2>{rename.kind==='folder'?'重命名分区':'重命名文献'}</h2><label>名称<input autoFocus aria-label="新名称" value={rename.name} onChange={e=>setRename({...rename,name:e.target.value})}/></label><div className="modal-actions"><button className="primary-button" type="submit" disabled={!rename.name.trim()}>保存名称</button></div></form></div>}
  {translation&&<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setTranslation(null);}}><div className="modal translation-modal"><button className="modal-close icon-btn" title="关闭翻译" onClick={()=>setTranslation(null)}><X size={18}/></button><h2><Languages size={21}/>划词翻译</h2><div className="translation-original">{translation.text}</div>{translateBusy?<div className="thinking"><LoaderCircle className="spin" size={16}/>正在理解语境与专业术语…</div>:<><h3>中文译文</h3><div className="prose"><Markdown>{translation.translation}</Markdown></div><h3>专业术语</h3>{translation.terms.length?<ul>{translation.terms.map((t,i)=><li key={i}>{t}</li>)}</ul>:<p className="muted">无单独列出的术语</p>}<h3>语境解释</h3><div className="prose"><Markdown>{translation.explanation}</Markdown></div><button className="subtle-button" onClick={()=>{persist({...paper,notes:paper.notes+'\n\n### 划词翻译\n\n> '+translation.text+'\n\n'+translation.translation+'\n\n'+translation.terms.join('\n')+'\n\n'+translation.explanation});setToast('译文已保存到笔记');}}><Plus size={14}/>保存到笔记</button></>}</div></div>}
  {newFolder&&<div className="modal-backdrop"><form className="modal folder-modal" onSubmit={e=>{e.preventDefault();if(!folderName.trim())return;setFolders([...folders,{id:crypto.randomUUID(),name:folderName.trim()}]);setFolderName('');setNewFolder(false);}}><h2>新建文献分区</h2><p>按课题、研究方向或阅读计划，整理你的文献。</p><input autoFocus aria-label="文件夹名称" value={folderName} onChange={e=>setFolderName(e.target.value)} placeholder="例如：骨关节炎机制" maxLength={40}/><div className="modal-actions"><button type="button" className="subtle-button" onClick={()=>setNewFolder(false)}>取消</button><button className="primary-button" type="submit">创建文件夹</button></div></form></div>}
  {imagePreview&&<div className="modal-backdrop" onClick={()=>setImagePreview(null)}><div className="image-modal"><div><strong>{imagePreview.title} · 原文所在页</strong><button className="icon-btn" title="关闭原图"><X size={20}/></button></div><img src={imagePreview.url} alt={imagePreview.title}/></div></div>}
  {toast&&<div className="toast" role="status"><CheckCircle2 size={16}/>{toast}</div>}
 </div></ReadingLinksContext.Provider>;
